<?php declare(strict_types=1); namespace App\People\Application\Command\AddFamilyAddress; use App\People\Domain\Enum\AddressType; use App\People\Domain\Model\Address; use App\People\Domain\Repository\PersonProfileRepository; use App\People\Domain\ValueObject\AddressId; use App\People\Domain\ValueObject\FamilyId; #[\Symfony\Component\Messenger\Attribute\AsMessageHandler] final readonly class AddFamilyAddressHandler {public function __construct(private PersonProfileRepository $repo){} public function __invoke(AddFamilyAddressCommand $c):AddressId{$id=AddressId::generate();$this->repo->addFamilyAddress(FamilyId::fromString($c->familyId),Address::create($id,AddressType::from($c->type),$c->line1,$c->line2,$c->city,$c->province,$c->postalCode,$c->country));return $id;}}